<?php $title = 'บริการ'; $categories = \App\Models\Service::CATEGORIES; $isAdmin = auth()->user()->hasRole('admin'); require __DIR__.'/../layouts/header.php'; ?>
<div class="page-actions"><p>รายการบริการ ราคา และระยะเวลา</p><?php if ($isAdmin): ?><a class="button" href="<?= e(route('services.create')) ?>">+ เพิ่มบริการ</a><?php endif; ?></div>
<?php require __DIR__.'/../partials/messages.php'; ?>
<section class="card"><form class="filter-form" method="get"><label for="q">ค้นหาบริการ</label><div class="filter-controls"><input id="q" name="q" value="<?= e($q) ?>"><select name="category" aria-label="ประเภท"><option value="">ทุกประเภท</option><?php foreach ($categories as $key => $label): ?><option value="<?= e($key) ?>" <?= ($filters['category'] ?? '') === $key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select><select name="active" aria-label="สถานะ"><option value="">ทุกสถานะ</option><option value="1" <?= ($filters['active'] ?? '') === '1' ? 'selected' : '' ?>>เปิดใช้</option><option value="0" <?= ($filters['active'] ?? '') === '0' ? 'selected' : '' ?>>ปิดใช้</option></select><button>ค้นหา</button></div></form>
<div class="table-wrap"><table><thead><tr><th>บริการ</th><th>ประเภท</th><th>ราคา</th><th>ระยะเวลา</th><th>สถานะ</th><?php if ($isAdmin): ?><th></th><?php endif; ?></tr></thead><tbody>
<?php foreach ($services as $service): ?><tr><td><?= e($service->name) ?></td><td><?= e($categories[$service->category]) ?></td><td><?= e($service->price) ?> บาท</td><td><?= e($service->duration_minutes) ?> นาที</td><td><span class="badge <?= $service->is_active ? 'good' : 'muted' ?>"><?= $service->is_active ? 'เปิดใช้' : 'ปิดใช้' ?></span></td><?php if ($isAdmin): ?><td><a href="<?= e(route('services.edit', $service)) ?>">แก้ไข</a></td><?php endif; ?></tr><?php endforeach; ?>
<?php if ($services->isEmpty()): ?><tr><td colspan="6" class="empty-state">ยังไม่มีบริการตามเงื่อนไข</td></tr><?php endif; ?></tbody></table></div><?php $paginator = $services; require __DIR__.'/../partials/pagination.php'; ?></section>
